#include <stdio.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    // Consumir o restante da primeira linha (incluindo o \n)
    int c;
    while ((c = getchar()) != '\n' && c != EOF);

    int abertas = 0;
    int valido = 1;
    char linha[256];

    for (int i = 0; i < n; i++) {
        if (fgets(linha, sizeof(linha), stdin) != NULL) {
            for (int j = 0; linha[j] != '\0'; j++) {
                if (linha[j] == '{') {
                    abertas++;
                } else if (linha[j] == '}') {
                    abertas--;
                    if (abertas < 0) {
                        valido = 0;
                    }
                }
            }
        }
    }

    if (valido && abertas == 0) {
        printf("S\n");
    } else {
        printf("N\n");
    }

    return 0;
}
